update public.questions set subject = 'Polity', topic = 'Federalism & Special Provisions', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about Indian federalism since 1990:', body_hi = '1990 के बाद से भारतीय संघवाद के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None of the statements is correct. Statement 1 reverses the trend: with no single party dominant, parties from the States became partners in governments at the Centre, which gave the States a larger say and strengthened the culture of power sharing and respect for State autonomy. Statement 2 reverses Bommai: the Court held that a Proclamation under Article 356 is open to judicial review, and that a government''s majority should be tested on the floor of the House, not judged from the Governor''s office. Statement 3 is wrong: Article 356 has been used many times since 1990, though less freely after Bommai.', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 प्रवृत्ति को उलट देता है: किसी एक दल का प्रभुत्व न रहने पर राज्यों के दल केंद्र की सरकारों में साझेदार बने, जिससे राज्यों की भूमिका बढ़ी और सत्ता की साझेदारी तथा राज्यों की स्वायत्तता के सम्मान की संस्कृति मज़बूत हुई। कथन 2 बोम्मई को उलट देता है: न्यायालय ने माना कि अनुच्छेद 356 की उद्घोषणा न्यायिक समीक्षा के अधीन है, और सरकार का बहुमत सदन के पटल पर परखा जाना चाहिए, राज्यपाल के कार्यालय से तय नहीं होना चाहिए। कथन 3 गलत है: 1990 के बाद अनुच्छेद 356 का कई बार प्रयोग हुआ है, यद्यपि बोम्मई के बाद कम खुले हाथ से।', concept_group_id = 'l1-pol-federalism-since-1990-bommai', source_citation = 'NCERT Class X, Democratic Politics -- II, Chapter 2 (Federalism); Supreme Court of India, S.R. Bommai v. Union of India (1994).', question_data = '{"statements": ["The rise of regional parties and coalition governments reduced the States'' say in forming the government at the Centre.", "In S.R. Bommai (1994), the Supreme Court held that the Governor''s report recommending President''s Rule is final and cannot be examined by the courts.", "Article 356 has not been used even once since 1990."], "statements_hi": ["क्षेत्रीय दलों और गठबंधन सरकारों के उदय ने केंद्र में सरकार बनाने में राज्यों की भूमिका घटाई।", "एस.आर. बोम्मई (1994) में सर्वोच्च न्यायालय ने माना कि राष्ट्रपति शासन की सिफ़ारिश करने वाली राज्यपाल की रिपोर्ट अंतिम है और न्यायालय उसकी जाँच नहीं कर सकते।", "1990 के बाद से अनुच्छेद 356 का एक बार भी प्रयोग नहीं हुआ है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l1-pol-federalism-since-1990-bommai' returning concept_group_id;
update public.questions set subject = 'Polity', topic = 'Constitutional & Statutory Bodies', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about a State Human Rights Commission:', body_hi = 'राज्य मानवाधिकार आयोग के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None of the statements is correct. Statement 1 is wrong in the committee: under the Protection of Human Rights Act, 1993, the Governor appoints the Chairperson and members on the recommendation of a committee headed by the Chief Minister, with the Speaker, the State''s Home Minister and the Leader of the Opposition; no judge sits on it, though the Chairperson must be a person who has been a Chief Justice or Judge of a High Court. Statement 2 is wrong: although the Governor appoints them, they can be removed only by the President, on the grounds and in the manner set out in the Act -- a safeguard for their independence. Statement 3 is wrong: the Act bars a Commission from taking up a matter pending before another Commission, so that two bodies do not inquire into the same case.', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 समिति में गलत है: मानवाधिकार संरक्षण अधिनियम, 1993 के तहत राज्यपाल मुख्यमंत्री की अध्यक्षता वाली समिति की सिफ़ारिश पर अध्यक्ष और सदस्यों की नियुक्ति करते हैं, जिसमें विधानसभा अध्यक्ष, राज्य के गृह मंत्री और विपक्ष के नेता होते हैं; इसमें कोई न्यायाधीश नहीं होता, यद्यपि अध्यक्ष वही हो सकता है जो किसी उच्च न्यायालय का मुख्य न्यायाधीश या न्यायाधीश रहा हो। कथन 2 गलत है: यद्यपि नियुक्ति राज्यपाल करते हैं, उन्हें केवल राष्ट्रपति ही अधिनियम में दिए आधारों और तरीके से हटा सकते हैं -- यह उनकी स्वतंत्रता का एक सुरक्षा उपाय है। कथन 3 गलत है: अधिनियम किसी आयोग को दूसरे आयोग के समक्ष लंबित मामला उठाने से रोकता है, ताकि दो निकाय एक ही मामले की जाँच न करें।', concept_group_id = 'l1-pol-state-human-rights-commission', source_citation = 'Protection of Human Rights Act, 1993, Sections 22, 23 and 36.', question_data = '{"statements": ["Its Chairperson is appointed by the Governor on the recommendation of a committee headed by the Chief Justice of the High Court.", "Its Chairperson can be removed from office by the Governor.", "It can inquire into a matter that is already being inquired into by the National Human Rights Commission."], "statements_hi": ["इसके अध्यक्ष की नियुक्ति राज्यपाल उच्च न्यायालय के मुख्य न्यायाधीश की अध्यक्षता वाली समिति की सिफ़ारिश पर करते हैं।", "इसके अध्यक्ष को राज्यपाल पद से हटा सकते हैं।", "यह उस मामले की जाँच कर सकता है जिसकी जाँच राष्ट्रीय मानवाधिकार आयोग पहले से कर रहा हो।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l1-pol-state-human-rights-commission' returning concept_group_id;
update public.questions set subject = 'Polity', topic = 'Panchayati Raj & Local Governance', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the debate on local government in the Constituent Assembly:', body_hi = 'संविधान सभा में स्थानीय शासन पर बहस के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'None of the statements is correct. Statement 1 is wrong in the unit: Gandhi''s idea of gram swaraj placed the self-governing village, not the district, at the base of the polity. Statement 2 is the reverse: Ambedkar feared that village life was marked by caste and faction and called the village ''a sink of localism, a den of ignorance, narrow-mindedness and communalism'', so the Assembly chose not to make it the basic unit. Statement 3 is wrong: the original Constitution only directed the State to organise village panchayats as a Directive Principle; regular elections became compulsory only with the 73rd Amendment of 1992.', explanation_hi = 'कोई भी कथन सही नहीं है। कथन 1 इकाई में गलत है: गांधी के ग्राम स्वराज के विचार ने ज़िले को नहीं, स्वशासी गाँव को राज्य-व्यवस्था की नींव में रखा। कथन 2 उलटा है: अंबेडकर को आशंका थी कि ग्राम-जीवन जाति और गुटबाज़ी से ग्रस्त है और उन्होंने गाँव को ''स्थानीयता का गड्ढा, अज्ञान, संकीर्णता और सांप्रदायिकता का अड्डा'' कहा, इसलिए सभा ने उसे मूल इकाई न बनाने का निर्णय किया। कथन 3 गलत है: मूल संविधान ने केवल निदेशक तत्व के रूप में राज्य को ग्राम पंचायतों के संगठन का निर्देश दिया; नियमित चुनाव 1992 के 73वें संशोधन से ही अनिवार्य हुए।', concept_group_id = 'l1-pol-gandhi-ambedkar-village-debate', source_citation = 'NCERT Class XI, Political Science -- Indian Constitution at Work, Chapter 8 (Local Governments); Constituent Assembly Debates, 4 November 1948.', question_data = '{"statements": ["Gandhi had seen the district, rather than the village, as the basic unit of a decentralised political order.", "Ambedkar strongly favoured making the village the basic unit of the new Constitution.", "The Constitution as originally adopted made it compulsory for every State to hold elections to panchayats."], "statements_hi": ["गांधी गाँव के बजाय ज़िले को विकेंद्रीकृत राजनीतिक व्यवस्था की मूल इकाई मानते थे।", "अंबेडकर गाँव को नए संविधान की मूल इकाई बनाने के प्रबल पक्षधर थे।", "मूल रूप से अंगीकृत संविधान ने हर राज्य के लिए पंचायतों के चुनाव कराना अनिवार्य किया था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l1-pol-gandhi-ambedkar-village-debate' returning concept_group_id;
commit;
